  select $drill${"key":"ai_calls","fact":"ai_calls","mode":"definer","grain":"one row per model call (chat.request): the model that answered, its provider, tokens, cost, latency and status","label":"AI model calls","lanes":["platform","organization","mine"],"paths":[{"key":"what","label":"What","levels":["provider","model"]},{"key":"who","label":"Who","levels":["organization","person","session"]},{"key":"thread","label":"Conversation","levels":["conversation","request","iteration"]},{"key":"when","label":"When","levels":["at:day","at:hour","bucket_10m"]}],"views":[{"key":"cx_by_model","label":"Usage by model","question":{"by":["model","provider"],"show":["calls","cost","tokens_in","tokens_out","tokens_cached","tokens_total","latency"],"sort":{"key":"calls","direction":"desc"}}},{"key":"cx_by_provider","label":"Cost by provider","question":{"by":["provider"],"show":["calls","cost","tokens_total"],"sort":{"key":"calls","direction":"desc"}}},{"key":"cx_by_day","label":"Daily cost and tokens","question":{"by":["at:day"],"show":["calls","cost","tokens_in","tokens_out","tokens_cached"],"sort":{"key":"at:day","direction":"asc"}}},{"key":"cx_tokens_by_day","chart":{"stack":["tokens_in","tokens_out"]},"label":"Daily input and output tokens","question":{"by":["at:day"],"show":["tokens_in","tokens_out"],"sort":{"key":"at:day","direction":"asc"}}},{"key":"cx_by_origin","label":"Cost by origin","question":{"by":["origin"],"show":["calls","cost","tokens_in","tokens_out","tokens_cached","tokens_total"],"sort":{"key":"cost","direction":"desc"}}},{"key":"cx_cost_share","label":"Cost share by model","question":{"by":["model","provider"],"show":["cost","calls"],"sort":{"key":"cost","direction":"desc"}}},{"key":"cx_latency","label":"Latency by model","question":{"by":["model","provider"],"show":["latency","latency_median","calls"],"sort":{"key":"latency","direction":"desc"}}},{"key":"reconcile_calls","label":"Model-call cost by whether the ledger holds the request (to reconcile with th